# bash completion for thronectl. Generated by 'thronectl completion bash'.
# thronectl itself completes: 'thronectl __complete WORD... CURRENT' prints the candidates.

# __thronectl_unquote sets REPLY to $1 as the shell reads it, without its quotes and
# backslashes; it expands nothing.
__thronectl_unquote() {
    local s=$1 c q=
    REPLY=
    while [[ -n $s ]]; do
        c=${s:0:1} s=${s:1}
        if [[ $q == \' ]]; then
            [[ $c == \' ]] && q= || REPLY+=$c
        elif [[ $c == \\ ]]; then
            # Within "...", a backslash quotes only \ " $ and `.
            [[ $q == \" && $s != [\\\"\$\`]* ]] && REPLY+=$c
            REPLY+=${s:0:1} s=${s:1}
        elif [[ $c == [\"\'] && (-z $q || $c == "$q") ]]; then
            [[ -n $q ]] && q= || q=$c
        else
            REPLY+=$c
        fi
    done
}

_thronectl() {
    local rest=${COMP_LINE:0:COMP_POINT} w gap cur word head file fprefix prog out line value desc i n
    local directive=0 width=0 quoted= REPLY
    local -a words args values descs files paths
    words=() args=() values=() descs=() files=() paths=()

    # Join the words bash 4 and later split at = and :, as in --addr=127.0.0.1:9095.
    for ((i = 0; i < COMP_CWORD; i++)); do
        w=${COMP_WORDS[i]}
        gap=${rest%%"$w"*}
        rest=${rest:${#gap}+${#w}}
        n=${#words[@]}
        if ((n > 1)) && [[ -z $gap ]]; then
            words[n-1]=${words[n-1]}$w
        else
            words[n]=$w
        fi
    done
    w=${rest#"${rest%%[![:space:]]*}"}
    n=${#words[@]}
    if ((n > 1)) && [[ -n $rest && $rest == "$w" ]]; then
        cur=${words[n-1]}$w
        unset "words[n-1]"
    else
        cur=$w
    fi
    __thronectl_unquote "$cur"
    word=$REPLY
    # Readline replaces only $2: the end of the word after the last COMP_WORDBREAKS
    # character or an opening quote. The candidates are whole words.
    head=
    if [[ $cur == *"$2" ]]; then
        __thronectl_unquote "${cur%"$2"}"
        head=$REPLY
    fi

    __thronectl_unquote "${words[0]}"
    prog=$REPLY
    case $prog in
        "~/"*) prog=$HOME/${prog:2} ;;
    esac
    type -P "$prog" >/dev/null 2>&1 || prog=thronectl
    for ((i = 1; i < ${#words[@]}; i++)); do
        __thronectl_unquote "${words[i]}"
        args[i-1]=$REPLY
    done

    # Git Bash would turn /v1/status, which call takes, into a path under its own directory.
    case $OSTYPE in
        msys*) local -x MSYS2_ARG_CONV_EXCL="/v1${MSYS2_ARG_CONV_EXCL:+;$MSYS2_ARG_CONV_EXCL}" ;;
    esac
    out=$("$prog" __complete ${args[@]+"${args[@]}"} "$word" </dev/null 2>/dev/null)
    while IFS= read -r line; do
        case $line in
            "") ;;
            :[0-9]*) directive=${line#:} ;;
            *)
                value=${line%%$'\t'*}
                [[ $value == "$head"* ]] || continue
                values+=("${value:${#head}}")
                descs+=("${line:${#value}+1}")
                ;;
        esac
    done <<<"$out"

    COMPREPLY=()
    if ((directive & 6)); then
        # The file is the word, or the text after the first = of --key-file=FILE.
        file=$word fprefix= w=$cur
        if [[ $word == -*=* ]]; then
            fprefix=${word%%=*}= file=${word#*=} w=${cur#*=}
        fi
        [[ $w == [\"\']* ]] && quoted=1
        if [[ -n $quoted ]] && type compopt >/dev/null 2>&1; then
            # Readline completes a quoted file name better.
            if ((directive & 4)); then
                compopt -o dirnames 2>/dev/null
            else
                compopt -o default 2>/dev/null
            fi
            return 0
        fi
        if ((directive & 4)); then
            out=$(compgen -d -- "$file")
        else
            out=$(compgen -f -- "$file")
        fi
        while IFS= read -r line; do
            [[ -n $line && $fprefix$line == "$head"* ]] || continue
            value=$fprefix$line
            files+=("${value:${#head}}")
            paths+=("$line")
        done <<<"$out"
    fi

    n=$((${#values[@]} + ${#files[@]}))
    # In a list, show the descriptions as "value  (description)"; a single candidate, or
    # one at a time from menu-complete (%) or insert-completions (*), goes in as it is.
    if ((n > 1)) && [[ ${COMP_TYPE-} != 37 && ${COMP_TYPE-} != 42 ]]; then
        for value in ${values[@]+"${values[@]}"}; do
            ((${#value} > width)) && width=${#value}
        done
        ((w = ${COLUMNS:-80} - width - 6))
        for ((i = 0; w >= 10 && i < ${#values[@]}; i++)); do
            desc=${descs[i]}
            [[ -n $desc ]] || continue
            ((${#desc} > w)) && desc=${desc:0:w-3}...
            printf -v line '%-*s  (%s)' "$width" "${values[i]}" "$desc"
            values[i]=$line
        done
    fi
    if type compopt >/dev/null 2>&1; then
        ((directive & 6)) && compopt -o filenames 2>/dev/null
        ((directive & 1)) && compopt -o nospace 2>/dev/null
    else
        # bash 3.2, as on macOS, has no compopt: the script registers with -o nospace, and
        # the candidates bring their quotes and the space after them.
        for ((i = 0; i < ${#files[@]}; i++)); do
            [[ -z $quoted ]] || break
            line=${files[i]} value=
            [[ $line == "~/"* ]] && value="~/" line=${line:2}
            [[ -n $line ]] && printf -v line '%q' "$line"
            files[i]=$value$line
        done
        if ((n == 1 && ${#values[@]} == 1 && !(directive & 1))); then
            values[0]+=" "
        elif ((n == 1 && ${#files[@]} == 1)) && [[ -z $quoted ]]; then
            line=${paths[0]}
            [[ $line == "~/"* ]] && line=$HOME/${line:2}
            [[ -d $line ]] && files[0]+=/ || files[0]+=" "
        fi
    fi
    COMPREPLY=(${values[@]+"${values[@]}"} ${files[@]+"${files[@]}"})
    return 0
}

if type compopt >/dev/null 2>&1; then
    complete -F _thronectl thronectl thronectl.exe
else
    complete -o nospace -F _thronectl thronectl thronectl.exe
fi
